import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import Sidebar from "../components/Sidebar";

function QnA({ onHelp }) {
  const { subId } = useParams();
  const user = JSON.parse(localStorage.getItem("user"));

  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [title, setTitle] = useState("");
  const [body, setBody] = useState("");

  useEffect(() => {
    async function load() {
      try {
        const res = await fetch(`http://localhost:8080/qa/posts?subId=${subId || ""}`);
        const data = await res.json();
        setPosts(data.posts || []);
      } catch (err) {
        console.error("QnA load error:", err);
      } finally {
        setLoading(false);
      }
    }

    load();
  }, [subId]);

  if (!user) return <h1 style={{ color: "white" }}>Please log in</h1>;

  async function createPost(e) {
    e.preventDefault();
    try {
      const res = await fetch("http://localhost:8080/qa/posts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, sub_id: subId, title, body }),
      });

      const data = await res.json();
      if (res.ok) {
        setPosts((p) => [data.post, ...p]);
        setTitle("");
        setBody("");
      } else {
        alert(data.message || "Could not create post.");
      }
    } catch (err) {
      console.error(err);
      alert("Failed to create post.");
    }
  }

  async function addReply(postId, replyBody) {
    try {
      const res = await fetch(`http://localhost:8080/qa/posts/${postId}/replies`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id, body: replyBody }),
      });
      const data = await res.json();
      if (res.ok) {
        setPosts((prev) => prev.map((p) => (p.id === postId ? { ...p, replies: [...(p.replies || []), data.reply] } : p)));
        if (onHelp) onHelp(subId);
      }
    } catch (err) {
      console.error(err);
    }
  }

  async function likePost(postId) {
    try {
      const res = await fetch(`http://localhost:8080/qa/posts/${postId}/likes`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ user_id: user.id }),
      });
      const data = await res.json();
      if (res.ok) {
        setPosts((prev) => prev.map((p) => (p.id === postId ? { ...p, likes: (p.likes || 0) + 1 } : p)));
      }
    } catch (err) {
      console.error(err);
    }
  }

  return (
    <div className="dashboard-page">
      <Sidebar />

      <main className="dashboard-main">
        <header className="dashboard-header">
          <div>
            <h1>Q & A</h1>
            <p className="dashboard-subtitle">Ask questions or help other students.</p>
          </div>
        </header>

        {loading ? (
          <p className="dashboard-loading">Loading posts...</p>
        ) : (
          <div className="dashboard-panel">
            <form onSubmit={createPost} className="card">
              <label>
                Title
                <input value={title} onChange={(e) => setTitle(e.target.value)} required />
              </label>

              <label>
                Question
                <textarea value={body} onChange={(e) => setBody(e.target.value)} required />
              </label>

              <button className="primary-btn" type="submit">Post Question</button>
            </form>

            <div style={{ marginTop: 16 }}>
              {posts.length === 0 ? (
                <p className="empty-text">No questions yet.</p>
              ) : (
                posts.map((p) => (
                  <div key={p.id} className="card" style={{ marginBottom: 12 }}>
                    <h3>{p.title}</h3>
                    <p className="small muted">by {p.user_name || p.userName}</p>
                    <p>{p.body}</p>
                    <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
                      <button className="secondary-btn" onClick={() => likePost(p.id)}>Like ({p.likes || 0})</button>
                      <ReplyBox post={p} onReply={(text) => addReply(p.id, text)} />
                    </div>

                    {p.replies && p.replies.length > 0 && (
                      <div style={{ marginTop: 10 }}>
                        <h4>Replies</h4>
                        {p.replies.map((r) => (
                          <div key={r.id} style={{ borderTop: "1px solid rgba(255,255,255,0.03)", paddingTop: 8 }}>
                            <p className="small muted">{r.user_name || r.userName}</p>
                            <p>{r.body}</p>
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

function ReplyBox({ post, onReply }) {
  const [open, setOpen] = useState(false);
  const [text, setText] = useState("");

  return (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      {!open ? (
        <button className="ghost-btn" onClick={() => setOpen(true)}>Reply</button>
      ) : (
        <form
          onSubmit={(e) => {
            e.preventDefault();
            if (text.trim()) onReply(text);
            setText("");
            setOpen(false);
          }}
        >
          <input value={text} onChange={(e) => setText(e.target.value)} placeholder="Write a reply..." />
          <button className="primary-btn" type="submit">Send</button>
        </form>
      )}
    </div>
  );
}

export default QnA;
